def f(N: int, A: Tuple[int, int, int], B: Tuple[int, int, int]) -> int:
    g_A, s_A, b_A = A
    g_B, s_B, b_B = B

    results = [0] * (N + 1)

    # iterate through all possible scores
    for g in range(g_A, g_B + 1):
        for s in range(s_A, s_B + 1):
            for b in range(b_A, b_B + 1):
                total_score = 3 * g + 2 * s + b
                if total_score > N:
                    continue
                results[total_score] = max(results[total_score], g + s + b)

    # calculate maximum result
    return max(results)
```

