def merge_sorted_arrays(A, B):
    idxA = len(A) - 1
    idxB = len(B) - 1
    while idxA >= 0 and idxB >= 0:
        if A[idxA] > B[idxB]:
            A[idxA + idxB + 1] = A[idxA]
            idxA -= 1
        else:
            A[idxA + idxB + 1] = B[idxB]
            idxB -= 1
    while idxB >= 0:
        A[idxA + idxB + 1] = B[idxB]
        idxB -= 1
    return A
